39	import org.springframework.samples.petclinic.model.Pet;
40	import org.springframework.samples.petclinic.model.Visit;
41	import org.springframework.samples.petclinic.rest.api.OwnersApi;
42	import org.springframework.samples.petclinic.rest.controller.CityOwnerLimitExceededException;
43	import org.springframework.samples.petclinic.rest.controller.DailyOwnerLimitExceededException;
44	import org.springframework.samples.petclinic.rest.controller.DuplicateHouseholdException;
45	import org.springframework.samples.petclinic.rest.controller.DuplicateTelephoneException;
46	import org.springframework.samples.petclinic.rest.controller.InvalidEmailException;
